def escape(value):
    return html.escape(value, quote=True)

def render_article(slug, story, lang):
    data = story[lang]
    prefix = "" if lang == "en" else lang + "/"
    labels = LABELS[lang]
    sections = "".join("<section><h2>" + escape(heading) + "</h2>" + "".join(p if p.startswith("<ul>") else "<p>" + p + "</p>" for p in paragraphs) + "</section>" for heading, paragraphs in data["sections"])
    sources = "<section class='news-sources'><h2>" + labels["sources"] + "</h2><ul>" + "".join("<li><a href='" + url + "' rel='noopener noreferrer'>" + escape(SOURCE_LABELS.get(lang,{}).get(name,name)) + "</a></li>" for name,url in story["sources"]) + "</ul></section>"
    return "<main class=\"page-content\" id=\"main-content\"><article class=\"news-article\"><a href=\"/" + prefix + "blog/\">" + labels["news"] + "</a><img class=\"news-hero\" src=\"/assets/blog/" + story["image"] + "\" alt=\"" + escape(data["alt"]) + "\" width=\"1536\" height=\"1024\"><h1>" + escape(data["title"]) + "</h1><p class=\"blog-intro\">" + escape(data["dek"]) + "</p><p class=\"news-date\">" + labels["source"] + ": " + story["source_date"][lang] + " · " + labels["published"] + ": " + labels["published_date"] + "</p>" + sections + sources + "</article></main>"

for slug, story in STORIES.items():
    for lang in ("en", "es", "ar"):
        prefix = "" if lang == "en" else lang + "/"
        path = ROOT / prefix / "blog" / slug / "index.html"
        page = path.read_text(encoding="utf-8")
        data = story[lang]
        page = re.sub(r"<main\b[\s\S]*?</main>", lambda _: render_article(slug,story,lang), page, count=1)
        page = re.sub(r"<title>[\s\S]*?</title>", "<title>" + escape(SEO_TITLES[slug][lang] + " | Convertios") + "</title>", page, count=1)
        page = re.sub(r'<meta name="description" content="[^"]*">', '<meta name="description" content="' + escape(data["dek"]) + '">', page, count=1)
        for prop,value in (("og:title",data["title"]),("og:description",data["dek"]),("twitter:title",data["title"]),("twitter:description",data["dek"])):
            page = re.sub(r'<meta (?:property|name)="' + prop + r'" content="[^"]*">', lambda m: m.group(0).split(' content=')[0] + ' content="' + escape(value) + '">', page)
        def rewrite_json(match):
            obj=json.loads(match.group(1)); obj["headline"]=data["title"];obj["description"]=data["dek"];obj["datePublished"]=PUBLISHED
            return '<script type="application/ld+json">'+json.dumps(obj,ensure_ascii=False)+'</script>'
        page=re.sub(r'<script type="application/ld\+json">([\s\S]*?)</script>',rewrite_json,page,count=1)
        path.write_bytes(page.replace("\r\n", "\n").encode("utf-8"))

for lang in ("en","es","ar"):
    prefix="" if lang=="en" else lang+"/"
    path=ROOT/prefix/"blog"/"index.html"
    page=path.read_text(encoding="utf-8")
    for slug,story in STORIES.items():
        data=story[lang]
        pattern=r'(<a class="news-card" href="/'+prefix+'blog/'+slug+r'/">)([\s\S]*?)(</a>)'
        match=re.search(pattern,page)
        if not match: raise RuntimeError(f"Missing hub card: {lang} {slug}")
        card=match.group(2)
        card=re.sub(r'<div class="news-card-date">.*?</div>', '<div class="news-card-date">'+story["source_date"][lang]+' · '+LABELS[lang]["published_date"]+'</div>',card,count=1)
        card=re.sub(r'<h2>.*?</h2>', '<h2>'+escape(data["title"])+'</h2>',card,count=1)
        card=re.sub(r'<p>.*?</p>', '<p>'+escape(data["dek"])+'</p>',card,count=1)
        page=page[:match.start(2)]+card+page[match.end(2):]
    path.write_bytes(page.replace("\r\n", "\n").encode("utf-8"))
